$p = Start-Process -FilePath node -ArgumentList app.js -PassThru -NoNewWindow -RedirectStandardOutput out2.txt; Start-Sleep 4; $o = Get-Content out2.txt -Raw; $m = [regex]::Match($o, "port (\d+)"); if ($m.Success) { $port = $m.Groups[1].Value; try { $r = Invoke-WebRequest "http://localhost:$port/" -UseBasicParsing -TimeoutSec 5; Write-Host "HTTP $($r.StatusCode) - PASS" } catch { Write-Host "CURL FAILED: $_" } } else { Write-Host "NO PORT" }; Stop-Process -Id $p.Id -Force
